/* Heatmap: 12-week training consistency grid (Mon-first) */
function Heatmap(p){
  var history = p.history || [];
  var D = 24 * 3600 * 1000;
  var today = new Date(); today.setHours(0, 0, 0, 0);
  var monday = new Date(today.getTime() - ((today.getDay() + 6) % 7) * D);
  var start = monday.getTime() - 11 * 7 * D;
  var byDay = {};
  history.forEach(function(hh){
    var t = new Date(hh.date); if (!isFinite(t.getTime())) return;
    t.setHours(0, 0, 0, 0);
    byDay[t.getTime()] = (byDay[t.getTime()] || 0) + (hh.tonnage || 0);
  });
  var max = 1;
  for (var k in byDay) if (byDay[k] > max) max = byDay[k];
  var cells = [];
  for (var d = 0; d < 7; d++){
    for (var w = 0; w < 12; w++){
      var ts = start + w * 7 * D + d * D;
      var v = byDay[ts] || 0;
      var future = ts > today.getTime();
      var lvl = v <= 0 ? 0 : Math.min(4, 1 + Math.floor((v / max) * 3.999));
      cells.push({ ts: ts, v: v, lvl: lvl, future: future, isToday: ts === today.getTime(), idx: w * 7 + d });
    }
  }
  var shades = ["#15151b", hexMix("#15151b", ACC, 0.3), hexMix("#15151b", ACC, 0.55), hexMix("#15151b", ACC, 0.8), ACC];
  var dows = ["M", "", "W", "", "F", "", "S"];
  return h("div", null,
    h("div", { style: { display: "grid", gridTemplateColumns: "14px 1fr", gap: 6, alignItems: "start" } },
      h("div", { style: { display: "grid", gridTemplateRows: "repeat(7,1fr)", gap: 4, height: "100%" } },
        dows.map(function(t, i){ return h("span", { key: i, style: { fontFamily: "'JetBrains Mono', ui-monospace, monospace", fontSize: 8, color: "#55555e", lineHeight: 1, alignSelf: "center" } }, t); })),
      h("div", { style: { display: "grid", gridTemplateColumns: "repeat(12,1fr)", gridTemplateRows: "repeat(7,1fr)", gap: 4, gridAutoFlow: "column" } },
        cells.map(function(c){
          return h("div", { key: c.ts, className: "heatin", title: new Date(c.ts).toLocaleDateString() + (c.v ? " · " + Math.round(c.v).toLocaleString() + " kg" : ""),
            style: { aspectRatio: "1", borderRadius: 4, background: c.future ? "transparent" : shades[c.lvl],
              border: c.isToday ? "1px solid " + ACC : (c.future ? "1px dashed #1d1d24" : "1px solid transparent"),
              boxShadow: c.lvl >= 3 ? "0 0 6px " + ACC + "44" : "none",
              animationDelay: Math.min(c.idx * 5, 460) + "ms" } });
        }))),
    h("div", { style: { display: "flex", alignItems: "center", gap: 4, marginTop: 8, justifyContent: "flex-end" } },
      h("span", { style: { fontFamily: "'JetBrains Mono', ui-monospace, monospace", fontSize: 8, color: "#55555e", marginRight: 0 } }, "LESS"),
      shades.map(function(s, i){ return h("span", { key: i, style: { width: 9, height: 9, borderRadius: 4, background: s, display: "inline-block" } }); }),
      h("span", { style: { fontFamily: "'JetBrains Mono', ui-monospace, monospace", fontSize: 8, color: "#55555e", marginLeft: 0 } }, "MORE")));
}
