    lead: { fontSize: 14, lineHeight: 1.62, color: "#bcbcc6", marginTop: 6, marginBottom: 0, letterSpacing: "0.005em" },
    grain: { display: "none" },
    scan: { display: "none" },
    aur1: { position: "fixed", width: "70vmax", height: "70vmax", left: "-30vmax", top: "-34vmax", borderRadius: "50%", pointerEvents: "none", zIndex: 0, opacity: 0.35, filter: "blur(90px)", background: `radial-gradient(circle, ${ACC}12 0%, transparent 60%)` },
    aur2: { position: "fixed", width: "60vmax", height: "60vmax", right: "-28vmax", bottom: "-30vmax", borderRadius: "50%", pointerEvents: "none", zIndex: 0, opacity: 0.3, filter: "blur(90px)", background: `radial-gradient(circle, ${ACC2}0e 0%, transparent 60%)` },
    header: { position: "sticky", top: 0, zIndex: 10, background: "rgba(10,10,12,0.88)", backdropFilter: "blur(14px)", WebkitBackdropFilter: "blur(14px)", borderBottom: `1px solid ${BORDER}`, padding: "calc(13px + env(safe-area-inset-top)) 16px 12px", animation: "drop .5s ease" },
    headTop: { maxWidth: 880, margin: "0 auto", display: "flex", justifyContent: "space-between", alignItems: "center" },
    logoMark: { width: 34, height: 34, borderRadius: 10, background: `linear-gradient(135deg, ${ACC}, ${ACC2})`, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: `0 0 18px ${ACC}55, inset 0 1px 0 rgba(255,255,255,0.42), inset 0 -2px 5px rgba(0,0,0,0.30)` },
    brand: { fontFamily: "-apple-system, BlinkMacSystemFont, 'SF Pro Display', 'Segoe UI', Roboto, sans-serif", fontWeight: 800, fontSize: 17, letterSpacing: 0.5 },
    statusDot: { width: 9, height: 9, borderRadius: "50%", boxShadow: "0 0 8px currentColor" },
    phaseStrip: { maxWidth: 880, margin: "11px auto 0", display: "flex", alignItems: "center", gap: 8 },
    seg: { height: 4, flex: 1, background: "#2C2C2E", borderRadius: 4, transition: "all .4s ease" },
    segNow: { boxShadow: `0 0 8px ${ACC}` },
    dock: { position: "fixed", left: 0, right: 0, bottom: 0, zIndex: 30, pointerEvents: "none" },
    dockInner: { pointerEvents: "auto", display: "flex", background: "rgba(8,8,10,0.78)", backdropFilter: "blur(28px) saturate(1.6)", WebkitBackdropFilter: "blur(28px) saturate(1.6)", borderTop: "0.5px solid rgba(255,255,255,0.12)", padding: "6px 8px calc(8px + env(safe-area-inset-bottom))" },
    dockBtn: { flex: 1, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 3, padding: "6px 2px 4px", background: "transparent", border: "none", cursor: "pointer", position: "relative", zIndex: 1, transition: "color .18s ease", WebkitTapHighlightColor: "transparent" },
